CREATE TABLE member_wiki_figure_assets (id text PRIMARY KEY, version_id text NOT NULL REFERENCES member_wiki_document_versions(id), ordinal int NOT NULL, locator jsonb NOT NULL, caption text, context text, original_sha256 text NOT NULL, normalized_sha256 text NOT NULL, original_body bytea NOT NULL, normalized_body bytea NOT NULL, media_type text NOT NULL, width int NOT NULL, height int NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(version_id, ordinal));
